# ═══════════════════════════ বাছাই ও লেখা ═══════════════════════════
FINAL = True
TARGET = 1000
oldq = {q["question"] for q in OLD}
mine = Q[start:]
rest = Q[:start]  # আগের স্ক্রিপ্টের ছাঁচ থেকে তৈরি, কিন্তু প্রথম ৫০০-তে জায়গা পায়নি
seen, cand = set(oldq), []
for q in mine + rest:
    if q["question"] in seen: continue
    seen.add(q["question"]); cand.append(q)
fixed = [q for q in cand if not q.get("tpl")]
tpl = [q for q in cand if q.get("tpl")]
need = TARGET - len(fixed)
assert need > 0, len(fixed)
assert len(tpl) >= need, (len(tpl), need)
# প্রতিটি ছাঁচ থেকে সমান হারে, যাতে একই ধাঁচের প্রশ্ন কম কম আসে
groups = {}
for q in tpl: groups.setdefault(re.sub(r"[০-৯–]+", "#", q["question"]), []).append(q)
ratio = need / len(tpl)
picked = []
for grp in groups.values():
    k = max(1, round(len(grp) * ratio)); picked += rng.sample(grp, min(k, len(grp)))
if len(picked) > need: picked = rng.sample(picked, need)
elif len(picked) < need: picked += rng.sample([q for q in tpl if q not in picked], need - len(picked))
order = {id(q): i for i, q in enumerate(cand)}
NEW = sorted(fixed + picked, key=lambda q: order[id(q)])
assert len(NEW) == TARGET
# আগের ছাঁচের কিছু প্রশ্নে আয়োজক জুটির নাম ("দক্ষিণ কোরিয়া ও জাপান") ভুল অপশন হয়ে আসে; একক দেশের প্রশ্নে সেটা বদলাই
single = [c for c in g["countries"] if " ও " not in c]
for q in NEW:
    a = q["options"][q["answer"]]
    if " ও " in a or any(k in q["question"] for k in ("আয়োজক", "কোন দেশে হয়েছিল", "কোথায়")): continue
    for i, o in enumerate(q["options"]):
        if " ও " in o and i != q["answer"]:
            q["options"][i] = rng.choice([c for c in single if c not in q["options"] and c not in gavoid(a)])
for q in NEW:
    assert len(set(q["options"])) == 4 and 0 <= q["answer"] < 4, q
KEYS = ("category", "difficulty", "question", "options", "answer", "explanation")
rows = [dict(q) for q in OLD] + [{"id": 500 + i, **{k: q[k] for k in KEYS}} for i, q in enumerate(NEW, 1)]
assert [r["id"] for r in rows] == list(range(1, len(rows) + 1))
assert len({r["question"] for r in rows}) == len(rows)
json.dump(rows, open(os.path.join(here, "questions.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
